code.source:
#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> v = {5, 2, 9, 1, 7};
    sort(v.begin(), v.end(), [](int a, int b) { return a > b; });
    for (int x : v) {
        cout << x << " ";
    }
    cout << endl;
    int limit = 4;
    int big = count_if(v.begin(), v.end(), [limit](int x) { return x > limit; });
    cout << big << endl;
    return 0;
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

struct Student {
    string name;
    int marks;
};

int main() {
    vector<Student> s = {{"Asha", 91}, {"Ravi", 78}, {"Mia", 85}};
    sort(s.begin(), s.end(), [](const Student& a, const Student& b) { return a.marks > b.marks; });
    for_each(s.begin(), s.end(), [](const Student& st) { cout << st.name << " " << st.marks << endl; });
    return 0;
}

